package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamLitBank1 {
  private const val T = "බෞද්ධ සාහිත්‍යය, ජාතක කතා හා නූතන අභියෝග"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "බෞද්ධ සාහිත්‍යය හා ජාතක කතා අදාළ කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("බුදුරදුන් බෝසත් අවධියේදී පාරමිතා පුරන අයුරු දැක්වෙන කතා 550 ක් ඇතුළත් ග්‍රන්ථය කුමක්ද?", "පන්සිය පනස් ජාතක පොත", "මහාවංසය", "විසුද්ධිමග්ගය", "මිලින්දපඤ්හය", "කුරුණෑගල යුගයේදී සිංහලයට නගන ලද ජාතක පොත ජනප්‍රියය."),
    q("බෝසතාණන් වහන්සේ බුද්ධත්වයට පත්වීමට පෙර පූරණය කළ යුතු පාරමිතා ධර්ම කොපමණ සංඛ්‍යාවක් වේද?", "දශ පාරමිතා (පාරමිතා දීයකි)", "පහකි", "අටකි", "විසිපහකි", "දාන, සීල, නෙක්ඛම්ම, පඤ්ඤා, විරිය, ඛන්ති, සစ္ච, අධිට්ඨාන, මෙත්තා, උපේක්ෂා දීයකි."),
    q("ජාතක කතාවල එන 'වෙස්සන්තර ජාතකයෙන්' ප්‍රධාන වශයෙන් ප්‍රකට කෙරෙන උතුම් පාරමිතාව කුමක්ද?", "දාන පාරමිතාව (සර්වඥතා දානය)", "සීල පාරමිතාව", "ප්‍රඥා පාරමිතාව", "විරිය පාරමිතාව", "තම දූ පුතුන් හා බිසව පවා දන් දෙමින් වෙස්සන්තර බෝසතාණන් දාන පාරමිතාව පිරූහ."),
    q("සාවුන් රජු ලෙස සිටියදී ගිනිගත් ගින්නට තම සිරුර පිහිටුවා මස් පිදූ බෝසත් කතාව කුමක්ද?", "සස ජාතකය", "උම්මග්ග ජාතකය", "කුස ජාතකය", "ගුත්තිල ජාතකය", "ශක්‍රයා විසින් පරීක්ෂා කළ අවස්ථාවේ බෝසත් සසා මින් දාන පාරමිතාව පිරීය."),
    q("කළගුණ සැලකීමේ අගය පෙන්වන ප්‍රසිද්ධ ජාතක කතාවක් වන 'සෙරිවාණිජ ජාතකය' උගන්වන්නේ කුමක්ද?", "ලෝභකම විනාශයට මුල් වන බවත් කෘතගුණී බව අගය කළ යුතු බවත්", "ධනය එකතු කළ යුතු බව", "අනුන් රැවටිය යුතු බව", "කම්මැලි විය යුතු බව", "මසුරු මෝස්තරකාර වෙළෙන්දා විනාශ වූ අතර දානශීලී වෙළෙන්දා දියුණු විය."),
    q("බුද්ධි මහිමයෙන් හා ප්‍රඥාවෙන් ගැටලු විසඳූ මහෞෂධ පණ්ඩිතයන්ගේ කතාව ඇතුළත් ජාතකය කුමක්ද?", "උම්මග්ග ජාතකය", "වෙස්සන්තර ජාතකය", "කුස ජාතකය", "විධුර ජාතකය", "ප්‍රඥා පාරමිතාව මුල් කරගත් උම්මග්ග ජාතකය උතුම් කතාවකි."),
    q("කසී රජුගේ දියණිය වූ ප්‍රභාවතී කුමරිය දිනා ගැනීමට විරූපී රුවින් පැමිණ බෝසතුන් ක්‍රියා කළ ජාතකය කුමක්ද?", "කුස ජාතකය", "මහාසුදස්සන ජාතකය", "ඛන්තිවාදී ජාතකය", "වේන්ද්‍ර ජාතකය", "නෙළුම් මල් මාලාව ඔස්සේ කුස කුමරු ප්‍රභාවතී දිනා ගත්තේය."),
    q("අමාවතුර, සද්ධර්මරත්නාවලිය හා පූජාවලිය වැනි විශිෂ්ට ග්‍රන්ථ බිහි වූයේ බෞද්ධ සාහිත්‍යයේ කුමන යුගයකදීද?", "පොළොන්නරු හා දඹදෙණි යුගවලදී", "අනුරාධපුර යුගයේදී", "මහනුවර යුගයේදී", "නූතන යුගයේදී", "සිංහල ගද්‍ය සාහිත්‍යයේ ස්වර්ණ යුගය ලෙස දඹදෙණි යුගය හැඳින්වේ."),
    q("බුදුරදුන්ගේ 'ගුණ මහිමය' ප්‍රධාන වශයෙන් විස්තර කරමින් ගුරුළුගෝමීන් විසින් රචිත ග්‍රන්ථය කුමක්ද?", "අමාවතුර", "සද්ධර්මරත්නාවලිය", "පූජාවලිය", "බෝධිවංශය", "බුදුරදුන් දමනය කළ අයුරු කියැවෙන අමාවතුර සිංහල ගද්‍යයේ මුදුන්මල්කඩකි."),
    q("ධම්මපදට්ඨකථාව ඇසුරෙන් ධර්මසේන හිමියන් විසින් රචිත අතිශය ජනප්‍රිය ග්‍රන්ථය කුමක්ද?", "සද්ධර්මරත්නාවලිය", "අමාවතුර", "පූජාවලිය", "දහම් ගැට මාලාව", "ජීවිතයට ආදර්ශවත් කතා රැසක් සද්ධර්මරත්නාවලියේ අඩංගුය."),
    q("මයුර සංදේශය, තිසර සංදේශය, ගුත්තිල කාව්‍යය වැනි කෘති බිහි වූයේ බෞද්ධ සාහිත්‍යයේ කවර යුගයකදීද?", "කෝට්ටේ යුගයේදී", "අනුරාධපුර යුගයේදී", "පොළොන්නරු යුගයේදී", "මහනුවර යුගයේදී", "සංදේශ කාව්‍ය බහුලව බිහි වූයේ සවන පරාක්‍රමබාහු රජ සමයේ කෝට්ටේ යුගයේදීය."),
    q("සංගීත තරඟයකදී සිය ගුරුතුමා (මුසල) පරාජය කළ දිව්‍ය සංගීතඥයෙකු වූ ගුත්තිල කුමරුගේ කතාව ඇතුළත් කාව්‍යය කුමක්ද?", "ගුත්තිල කාව්‍යය (වැත්තෑවේ හිමි විසින් රචිත)", "කාව්‍යශේඛරය", "සංදේශය", "යශෝධරා වත", "කෝට්ටේ යුගයේදී වැත්තෑවේ හිමි ගුත්තිල කාව්‍යය රචනා කළහ."),
    q("නූතන සමාජයේ තරුණ පරපුර මුහුණපාන මත්ද්‍රව්‍ය උවදුර හා බුදුදහමින් දෙන විසඳුම කුමක්ද?", "පස්වන සිල්පදය රැකීම හා සිහිනුවණ දියුණු කිරීම", "මත්ද්‍රව්‍ය භාවිතය අනුමත කිරීම", "සමාජයෙන් පලා යාම", "නීති නොසලකා හැරීම", "පංච ශීලයෙන් හා මත්පැන් විරමණයෙන් තරුණ පරපුර රැකගත හැක."),
    q("තාක්ෂණයේ දියුණුවත් සමඟ අන්තර්ජාලය හා සමාජ ජාල නියමිත පරිදි භාවිත නොකිරීමෙන් ඇතිවන ගැටුම්වලට බෞද්ධ විසඳුම කුමක්ද?", "සති සම්පජඤ්ඤයෙන් (සිහිනුවණින්) යුතුව විචාරශීලීව භාවිත කිරීම", "තාක්ෂණය සම්පූර්ණයෙන් තහනම් කිරීම", "පරිගණක විනාශ කිරීම", "අන්තර්ජාලය නොබැලීම", "අයෝනිසෝ මනසිකාරයෙන් වැළකී යෝනිසෝ මනසිකාරයෙන් ක්‍රියා කළ යුතුය."),
    q("පවුල් සංස්ථාව බිඳවැටීමට හා දික්කසාද වැඩි වීමට මුල් වන ප්‍රධාන හේතුවක් ලෙස බුදුදහම පෙන්වන්නේ කුමක්ද?", "අඹුසැමි විශ්වාසය බිඳීම හා ආත්මාර්ථකාමීත්වය", "ආහාර හිඟකම", "උගත්කම වැඩි වීම", "රැකියා නැති වීම", "සමසද්ධා, සමසීල නොමැති වීම හා අවිශ්වාසය පවුල් බිඳවට්ටයි.")
  )
}
